package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.sequence.FastqIO;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

class TrimmomaticToolsCliTest {
    @TempDir(cleanup=CleanupMode.ON_SUCCESS) Path dir;private String output;
    private String home(String version){String v=System.getenv(version.equals("0.41")?"JLINALG_TRIMMOMATIC_041":"JLINALG_TRIMMOMATIC_039");assumeTrue(v!=null,"Set both original Trimmomatic runtime homes");return v;}
    private int run(String name,String... args)throws Exception{var a=new ArrayList<>(List.of("trimmomatic-tools","--out",dir.resolve(name).toString(),"--no-config"));a.addAll(List.of(args));var b=new ByteArrayOutputStream();var p=new PrintStream(b);int c=JLinAlgCli.run(a.toArray(String[]::new),p,p);output=b.toString();for(String f:List.of("WARNINGS.md","analysis.log"))if(c!=0&&Files.exists(dir.resolve(name).resolve(f)))output+=Files.readString(dir.resolve(name).resolve(f));return c;}
    private Path steps(String name,String body)throws Exception{Path p=dir.resolve(name+".tsv");Files.writeString(p,"step\targuments\n"+body);return p;}
    private Path reads(String name,int mate)throws Exception{Path p=dir.resolve(name+".fq");String[] names={"both","first","second","drop"};try(var out=new FastqIO.Writer(p)){for(int i=0;i<4;i++)out.write(new FastqIO.Read("@"+names[i]+"/"+mate+" comment "+i,"ACGTACGT",(i==0||i==mate?"IIIIIIII":"!!!!!!!!")));}return p;}
    private List<FastqIO.Read> contents(Path p)throws Exception{var out=new ArrayList<FastqIO.Read>();try(var in=new FastqIO.Reader(p)){FastqIO.Read r;while((r=in.next())!=null)out.add(r);}return out;}
    @Test void nativePairsPreserveAllFourFatesAndWarnAboutOrphans()throws Exception{Path a=reads("r1",1),b=reads("r2",2),s=steps("pipeline","LEADING\t20\nMINLEN\t2\n");assertEquals(0,run("native","--engine","native","--reads",a.toString(),"--reads2",b.toString(),"--phred","33","--steps",s.toString()),output);for(String f:List.of("read1.paired.fastq.gz","read2.paired.fastq.gz","read1.unpaired.fastq.gz","read2.unpaired.fastq.gz"))assertEquals(1,contents(dir.resolve("native/"+f)).size());assertTrue(Files.readString(dir.resolve("native/WARNINGS.md")).contains("ORPHANS RETAINED"));assertTrue(Files.readString(dir.resolve("native/read-status.tsv")).contains("dropped"));}
    @Test void original039And041MatchNativePairsHeadersSpansAndSummary()throws Exception{Path a=reads("r1",1),b=reads("r2",2),s=steps("pipeline","LEADING\t20\nMINLEN\t2\n");assertEquals(0,run("native","--engine","native","--reads",a.toString(),"--reads2",b.toString(),"--phred","33","--steps",s.toString()),output);for(String v:List.of("0.39","0.41")){assertEquals(0,run(v,"--engine","upstream","--home",home(v),"--reads",a.toString(),"--reads2",b.toString(),"--phred","33","--steps",s.toString()),output);for(String f:List.of("read1.paired.fastq.gz","read2.paired.fastq.gz","read1.unpaired.fastq.gz","read2.unpaired.fastq.gz"))assertEquals(contents(dir.resolve("native/"+f)),contents(dir.resolve(v+"/"+f)));assertEquals(Files.readAllLines(dir.resolve("native/trim.log")),Files.readAllLines(dir.resolve(v+"/trim.log")));}}
    @Test void missingRuntimeSkipsBeforeOpeningInputsWithActionableRecovery()throws Exception{assertEquals(3,run("missing","--engine","upstream","--home",dir.resolve("absent").toString(),"--reads","missing","--steps","missing","--phred","33"),output);assertTrue(Files.readString(dir.resolve("missing/WARNINGS.md")).contains("install_trimmomatic.py --allow-download"));assertFalse(Files.exists(dir.resolve("missing/results.tsv")));}
    @Test void singleEndHeadCropThenPhredConversionMatchesBothProgramsAndRetainsAllFilteredWarning()throws Exception{
        Path reads=dir.resolve("single.fq");Files.writeString(reads,"@read comment\nACGTACGTACGTACGT\n+\n"+"h".repeat(16)+"\n");Path s=steps("crop","HEADCROP\t10\nTOPHRED33\nMINLEN\t5\n");assertEquals(0,run("single-native","--engine","native","--reads",reads.toString(),"--phred","64","--steps",s.toString()),output);assertEquals(new FastqIO.Read("@read comment","GTACGT","I".repeat(6)),contents(dir.resolve("single-native/trimmed.fastq.gz")).get(0));for(String v:List.of("0.39","0.41")){assertEquals(0,run("single-"+v,"--engine","upstream","--home",home(v),"--reads",reads.toString(),"--phred","64","--steps",s.toString()),output);assertEquals(contents(dir.resolve("single-native/trimmed.fastq.gz")),contents(dir.resolve("single-"+v+"/trimmed.fastq.gz")));}
        s=steps("all","MINLEN\t100\n");assertEquals(0,run("all","--engine","native","--reads",reads.toString(),"--phred","64","--steps",s.toString()),output);assertTrue(Files.readString(dir.resolve("all/WARNINGS.md")).contains("NO READS RETAINED"));assertTrue(contents(dir.resolve("all/trimmed.fastq.gz")).isEmpty());
    }
    private String reverse(String sequence){var s=new StringBuilder();for(int i=sequence.length()-1;i>=0;i--)s.append("TGCA".charAt("ACGT".indexOf(sequence.charAt(i))));return s.toString();}
    @Test void originalSimpleAdapterAndPalindromeModesRecoverIndependentSyntheticInsertTruth()throws Exception{
        String adapter="GTCAGCTACGATTCGAGTCCATGCTACGATCAGATCGTAC",insert="ACGTCGATCGTAGCTAGGCTACGATGCATCGTACGTAGCA";Path fasta=dir.resolve("synthetic adapters.fa"),reads=dir.resolve("adapter.fq");Files.writeString(fasta,">SyntheticAdapter\n"+adapter+"\n");Files.writeString(reads,"@adapter\n"+insert+adapter+"\n+\n"+"I".repeat(insert.length()+adapter.length())+"\n");Path simple=steps("simple","ILLUMINACLIP\t"+fasta.getFileName()+"\t2\t30\t10\nMINLEN\t10\n");
        for(String v:List.of("0.39","0.41")){var opts=new ArrayList<>(List.of("--engine","upstream","--home",home(v),"--reads",reads.toString(),"--phred","33","--steps",simple.toString()));if(v.equals("0.41"))opts.addAll(List.of("--verbose","true"));assertEquals(0,run("adapter-"+v,opts.toArray(String[]::new)),output);assertEquals(insert,contents(dir.resolve("adapter-"+v+"/trimmed.fastq.gz")).get(0).sequence());assertEquals(Files.readString(fasta),Files.readString(dir.resolve("adapter-"+v+"/adapters-step-0.fa")));}
        String prefix1="ACGTCAGCTAGTCGATCGTAGCTA",prefix2="TCGATGCATGCTAGCTACGATGCA",shortInsert="GATCGTACAGCTAGCATGCTAGTAC";Path a=dir.resolve("pal1.fq"),b=dir.resolve("pal2.fq");String seq1=shortInsert+reverse(prefix2),seq2=reverse(shortInsert)+reverse(prefix1);Files.writeString(a,"@pal/1\n"+seq1+"\n+\n"+"I".repeat(seq1.length())+"\n");Files.writeString(b,"@pal/2\n"+seq2+"\n+\n"+"I".repeat(seq2.length())+"\n");Files.writeString(fasta,">PrefixSynthetic/1\n"+prefix1+"\n>PrefixSynthetic/2\n"+prefix2+"\n");
        for(String v:List.of("0.39","0.41"))for(boolean keep:List.of(false,true)){Path s=steps("pal-"+v+keep,"ILLUMINACLIP\t"+fasta.getFileName()+"\t2\t30\t10\t2\t"+keep+"\nMINLEN\t5\n");String name="pal-"+v+keep;assertEquals(0,run(name,"--engine","upstream","--home",home(v),"--reads",a.toString(),"--reads2",b.toString(),"--phred","33","--steps",s.toString()),output);if(keep){assertEquals(shortInsert,contents(dir.resolve(name+"/read1.paired.fastq.gz")).get(0).sequence());assertEquals(reverse(shortInsert),contents(dir.resolve(name+"/read2.paired.fastq.gz")).get(0).sequence());}else{assertEquals(shortInsert,contents(dir.resolve(name+"/read1.unpaired.fastq.gz")).get(0).sequence());assertTrue(contents(dir.resolve(name+"/read2.unpaired.fastq.gz")).isEmpty());assertTrue(Files.readString(dir.resolve(name+"/WARNINGS.md")).contains("NO COMPLETE PAIRS"));}}
    }
    @Test void maxinfoPipelineMatchesBothActualProgramsAndDoesNotReduceLongInputsSilently()throws Exception{
        Path read=dir.resolve("maxinfo.fq");Files.writeString(read,"@max\n"+"ACGT".repeat(30)+"\n+\n"+"I".repeat(70)+"!".repeat(50)+"\n");Path s=steps("maxinfo","MAXINFO\t40\t0.5\nMINLEN\t20\n");assertEquals(0,run("max-native","--engine","native","--reads",read.toString(),"--phred","33","--steps",s.toString()),output);for(String v:List.of("0.39","0.41")){assertEquals(0,run("max-"+v,"--engine","upstream","--home",home(v),"--reads",read.toString(),"--phred","33","--steps",s.toString()),output);assertEquals(contents(dir.resolve("max-native/trimmed.fastq.gz")),contents(dir.resolve("max-"+v+"/trimmed.fastq.gz")));}Files.writeString(read,"@long\n"+"A".repeat(1001)+"\n+\n"+"I".repeat(1001)+"\n");assertEquals(2,run("long","--engine","native","--reads",read.toString(),"--phred","33","--steps",s.toString()),output);assertTrue(Files.readString(dir.resolve("long/WARNINGS.md")).contains("at most1000bases"));assertFalse(Files.exists(dir.resolve("long/results.tsv")));
    }
    @Test void duplicateHeadersRemainDistinctAndPairSlotEncodingPipelineMistakesFail()throws Exception{
        Path a=dir.resolve("duplicates1.fq"),b=dir.resolve("duplicates2.fq");Files.writeString(a,"@same/1\nACGT\n+\nIIII\n@same/1\nTGCA\n+\nIIII\n");Files.writeString(b,"@same/2\nCGTA\n+\nIIII\n@same/2\nGCAT\n+\nIIII\n");Path s=steps("pass","MINLEN\t1\n");assertEquals(0,run("duplicates","--engine","native","--reads",a.toString(),"--reads2",b.toString(),"--phred","33","--steps",s.toString()),output);assertEquals(List.of("ACGT","TGCA"),contents(dir.resolve("duplicates/read1.paired.fastq.gz")).stream().map(FastqIO.Read::sequence).toList());assertEquals(2,run("swapped","--engine","native","--reads",b.toString(),"--reads2",a.toString(),"--phred","33","--steps",s.toString()),output);assertTrue(Files.readString(dir.resolve("swapped/WARNINGS.md")).contains("mate label"));Files.writeString(a,"@bad\nACGT\n+\n!!!!\n");assertEquals(2,run("encoding","--engine","native","--reads",a.toString(),"--phred","64","--steps",s.toString()),output);assertTrue(Files.readString(dir.resolve("encoding/WARNINGS.md")).contains("declared Phred"));Path crop=steps("zero","CROP\t0\n");assertEquals(2,run("zero","--engine","native","--reads",a.toString(),"--phred","33","--steps",crop.toString()),output);
    }
    @Test void outputEncodingRangeAndOldJavaVersionGivePreciseFailureOrSkip()throws Exception{
        Path read=dir.resolve("high.fq");Files.writeString(read,"@high\nACGT\n+\n~~~~\n");Path s=steps("to64","TOPHRED64\n");assertEquals(2,run("range","--engine","native","--reads",read.toString(),"--phred","33","--steps",s.toString()),output);assertTrue(Files.readString(dir.resolve("range/WARNINGS.md")).contains("select TOPHRED33"));String java21=System.getenv("JLINALG_TRIMMOMATIC_OLD_JAVA");assumeTrue(java21!=null,"Supply explicit older Java for actual0.41minimum-runtime skip check");assertEquals(3,run("old-java","--engine","upstream","--home",home("0.41"),"--java",java21,"--reads","missing","--phred","33","--steps","missing"),output);assertTrue(Files.readString(dir.resolve("old-java/WARNINGS.md")).contains("requires Java25"));
    }
}
